/// <summary>
/// PaffH 03.09.22
/// helper class for CustTransOpen
/// </summary>
public class NDXCustTransOpenClass
{
    CustTransOpenPerDateDP custTransOpenPerDateDP;
    CustTransOpenPerDateContract custTransOpenPerDateContract;
    CustTransOpenPerDateTmp custTransOpenPerDateTmp;
    UserConnection userConnection;
    NDXSignature signature;

}

Method.Source:
/// <summary>
/// PaffH 03.09.22
/// </summary>
protected void new()
{
    userConnection = new UserConnection();
    signature = NDXHelperCommon::Signature();
}

/// <summary>
/// PaffH 03.09.22
/// </summary>
/// <returns>NDXCustTransOpenClass</returns>
public static NDXCustTransOpenClass construct()
{
    NDXCustTransOpenClass nDXCustTransOpen = new NDXCustTransOpenClass();
    return nDXCustTransOpen;
}

/// <summary>
/// PaffH 03.09.22
/// get CustTransOpen data
/// </summary>
/// <param name = "_custTransOpenPerDateContract">CustTransOpenPerDateContract</param>
/// <returns>CustTransOpenPerDateTmp</returns>
public CustTransOpenPerDateTmp populateData(CustTransOpenPerDateContract _custTransOpenPerDateContract)
{
    try
    {
        custTransOpenPerDateDP = new CustTransOpenPerDateDP();
        custTransOpenPerDateDP.parmDataContract(_custTransOpenPerDateContract);
        custTransOpenPerDateDP.parmUserConnection(userConnection);
        custTransOpenPerDateDP.processReport();
        custTransOpenPerDateTmp = custTransOpenPerDateDP.getCustTransOpenPerDateTmp();
        return custTransOpenPerDateTmp;
    }
    catch
    {
        throw Error("@NDX:NDXOpenTransDatenNotDetermined");
    }
}

/// <summary>
/// PaffH 03.09.22
/// populate ds with data from custTransOpen
/// </summary>
/// <param name = "_CustTransOpenPerDateTmp">CustTransOpenPerDateTmp</param>
/// <param name = "_custTransOpenPerDateContract">CustTransOpenPerDateContract</param>
public void populateData2DS(CustTransOpenPerDateTmp _CustTransOpenPerDateTmp, CustTransOpenPerDateContract _custTransOpenPerDateContract = null)
{
    if (_custTransOpenPerDateContract)
    {
        this.populateData(_custTransOpenPerDateContract);
    }            

    if (!FormDataUtil::isFormDataSource(_custTransOpenPerDateTmp))
    {
        throw Error("@NDX:NDXWrongCall");
    }
    delete_from _custTransOpenPerDateTmp;
    while select * from custTransOpenPerDateTmp
    {
        buf2Buf(custTransOpenPerDateTmp, _custTransOpenPerDateTmp);
        _custTransOpenPerDateTmp.insert();
    }
    FormDataSource fds = FormDataUtil::getFormDataSource(_custTransOpenPerDateTmp);
    fds.research();
}
